import java.util.*;

class Solution {
    private Map<TreeNode, TreeNode> parent = new HashMap<>();
    private TreeNode start = null;

    public List<Integer> distanceK(TreeNode root, int target, int k) {
        link(root, null, target);
        Deque<TreeNode> q = new ArrayDeque<>();
        Set<TreeNode> seen = new HashSet<>();
        q.add(start);
        seen.add(start);
        for (int step = 0; step < k && !q.isEmpty(); step++) {
            int size = q.size();
            for (int i = 0; i < size; i++) {
                TreeNode n = q.poll();
                // neighbours: both children and the parent
                for (TreeNode m : new TreeNode[]{n.left, n.right, parent.get(n)}) {
                    if (m != null && seen.add(m)) q.add(m);
                }
            }
        }
        List<Integer> out = new ArrayList<>();
        for (TreeNode n : q) out.add(n.val);
        Collections.sort(out);
        return out;
    }

    // record parent of every node and locate the target node
    private void link(TreeNode n, TreeNode p, int target) {
        if (n == null) return;
        parent.put(n, p);
        if (n.val == target) start = n;
        link(n.left, n, target);
        link(n.right, n, target);
    }
}

