class Solution:
    def distanceK(self, root: Optional[TreeNode], target: int, k: int) -> List[int]:
        adj = defaultdict(list); st = [root]
        while st:
            n = st.pop()
            for c in (n.left, n.right):
                if c: adj[n.val].append(c.val); adj[c.val].append(n.val); st.append(c)
        seen = {target}; fr = [target]
        for _ in range(k):
            nx = []
            for v in fr:
                for w in adj[v]:
                    if w not in seen: seen.add(w); nx.append(w)
            fr = nx
        return sorted(fr)

