function distanceK(root, target, k) {
  const par = new Map(); let t = null;
  const go = (n, p) => { if (!n) return; par.set(n, p); if (n.val === target) t = n; go(n.left, n); go(n.right, n); };
  go(root, null);
  const out = [];
  const walk = (n, from, d) => {
    if (!n) return;
    if (d === k) { out.push(n.val); return; }
    for (const m of [n.left, n.right, par.get(n)]) if (m && m !== from) walk(m, n, d + 1);
  };
  walk(t, null, 0);
  return out.sort((a, b) => a - b);
}
